#pragma once
// Gegenereerd door tools/ts/trains.py model: maten van de Train Simulator-modellen (data/trains/<naam>).
// Per rijtuig (voorste eerst, cabine aan +z): afstand tussen de koppelpunten en de deuropeningen (z, midden).
// Bestemmingsborden: soort (0 voor, 1 zijkant), midden x y z en de richting waarin het bord kijkt (nx, nz).
#include <cstring>

struct TsSign { int kind; float x, y, z, nx, nz; };
// Zitplaatsen uit de stoelen in het TS-interieur: x, z (midden zitting), kijkrichting (0 = +z), vloerhoogte.
struct TsSeat { float x, z, facing, y; };
// Cabine (eindrijtuig): cabinewand (z), vloer en oog van de machinist (CabCam). Reizigerscamera (PassCam) in het
// passagiersinterieur: oog en kijkrichting, en de raamcamera (zelfde rijtuig).
struct TsCab { int ok; float wallZ, floorY, x, y, z; };
struct TsCam { int ok; float x, y, z, dx, dz, wx, wy, wz, wdx, wdz; };
struct TsCarLayout { float pitch; int doors; float doorZ[4]; int signs; TsSign sign[4]; int seats; const TsSeat* seat; TsCab cab; TsCam pass; };
struct TsLayout { const char* name; int cars; TsCarLayout car[8]; };

